import {demo,assess,parseCSV} from './engine.js';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem('supplysignal-v1'));if(!Array.isArray(state?.orders)||!Array.isArray(state?.logs))state=null;}catch{}state??={orders:structuredClone(demo),actions:{},logs:[]};state.actions??={};let filter='Exceptions',selected=null;const save=()=>{try{localStorage.setItem('supplysignal-v1',JSON.stringify(state));}catch{toast('Browser storage unavailable; changes remain in this session.');}};function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}const date=s=>new Date(s+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
function render(){const all=state.orders.map(assess),critical=all.filter(r=>r.severity==='Critical');$('#metrics').innerHTML=[['Open exceptions',all.filter(r=>r.severity!=='On track'&&!state.actions[r.po]).length,'Awaiting an operator action'],['Critical order lines',critical.length,'Late for production or short quantity'],['Exposed job references',new Set(critical.map(r=>r.job)).size,'Jobs linked to critical order lines'],['Actions recorded',Object.keys(state.actions).length,'Reviewed by a human operator']].map(([l,n,s])=>`<div class="metric"><label>${l}</label><strong>${n.toString().padStart(2,'0')}</strong><small>${s}</small></div>`).join('');let rows=all.filter(r=>(filter==='All'||filter==='Critical'&&r.severity==='Critical'||filter==='Exceptions'&&r.severity!=='On track')&&Object.values(r).join(' ').toLowerCase().includes($('#search').value.toLowerCase())).sort((a,b)=>({Critical:0,Watch:1,'On track':2}[a.severity]-{Critical:0,Watch:1,'On track':2}[b.severity])||b.slip-a.slip);$('#count').textContent=rows.length;$('#rows').innerHTML=rows.length?rows.map(r=>`<tr><td><b>${esc(r.po)}</b><small>${esc(r.supplier)}</small></td><td><b>${esc(r.part)}</b><small>${esc(r.job)}</small></td><td><span class="${r.late||r.short?'signal':''}">${r.late?`${r.late}d past promise`:r.short?'Quantity short':'On schedule'}${r.short?` · ${r.short} short`:''}</span><small>Due ${date(r.due)} → ETA ${date(r.eta)}</small></td><td><span class="badge ${r.severity}">${r.severity}</span></td><td><button data-po="${esc(r.po)}">${state.actions[r.po]?'View action ↗':'Review →'}</button></td></tr>`).join(''):'<tr><td colspan="5">No matching orders. Try another search or view all orders.</td></tr>';document.querySelectorAll('[data-po]').forEach(b=>b.onclick=()=>openDetail(b.dataset.po));document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));}
function draft(r){return `Subject: Delivery confirmation needed — ${r.po}\n\nHello ${r.supplier},\n\nPlease confirm recovery options for ${r.part}. Our order is ${r.ordered} units; your current confirmation is ${r.confirmed} units arriving ${r.eta}, against the original ${r.due} promise.\n\nProduction requires this order by ${r.need} for ${r.job}.${r.slip?` The current ETA is ${r.slip} day(s) after that need date.`:''}${r.short?` We also need a plan for the ${r.short}-unit shortfall.`:''}\n\nCan you confirm an earlier shipment, a split delivery, or a revised quantity and date? Please provide options for our approval.\n\nThank you,\nSupplier Operations`;}
function openDetail(po){selected=po;const r=assess(state.orders.find(x=>x.po===po));$('#detailBody').innerHTML=`<h2>${esc(r.po)} · ${esc(r.supplier)}</h2><p>${esc(r.part)}</p><div class="facts"><b>Why this is ${r.severity.toLowerCase()}</b><br>${r.slip?`Arrival misses the job need date by <b>${r.slip} days</b>.`:'Arrival meets the job need date.'}<br>${r.short?`Confirmed quantity is <b>${r.short} units short</b>.`:'Full order quantity is confirmed.'}<br>Job: ${esc(r.job)} · needed ${date(r.need)}<br>Original promise: ${date(r.due)} · Current ETA: ${date(r.eta)}<br>Source: order line ${esc(r.po)}; no inventory or alternate-stock check.</div><h3>Suggested next step</h3><p>${r.severity==='Critical'?'Request a recovery plan and alert the production planner.':r.severity==='Watch'?'Confirm the revised ETA while the job still has delivery buffer.':'No delivery exception. Monitor future supplier changes.'}</p><h3>Supplier follow-up draft</h3><textarea id="draft" aria-label="Supplier follow-up draft"></textarea><div class="actions"><button id="copy">Copy draft</button><button id="downloadDraft">Download draft</button><button id="record" class="primary">${state.actions[po]?'Action already recorded':'Record follow-up action'}</button></div><p style="font-size:10px;margin-top:12px">Draft only. Review before sending. Recording an action does not send a message or resolve the delivery risk.</p>`;$('#draft').value=state.actions[po]?.draft??draft(r);$('#record').disabled=!!state.actions[po];$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#draft').value);toast('Draft copied.');}catch{toast('Copy unavailable. Download the draft instead.');}};$('#downloadDraft').onclick=()=>download(`${po}-follow-up.txt`,$('#draft').value,'text/plain');$('#record').onclick=()=>{const time=new Date().toISOString();state.actions[po]={draft:$('#draft').value,time};state.logs.unshift({time,text:`Follow-up action recorded for ${po}. No message sent.`});save();render();$('#detail').close();toast('Follow-up recorded. Delivery risk remains visible.');};$('#detail').showModal();}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}const csvCell=v=>'"'+String(v).replaceAll('"','""')+'"';const keys=['po','supplier','part','ordered','confirmed','due','eta','job','need','units'];$('#template').onclick=()=>download('supplier-orders-template.csv',[keys.join(','),...demo.map(r=>keys.map(k=>csvCell(r[k])).join(','))].join('\r\n'),'text/csv');$('#export').onclick=()=>{const rows=state.orders.map(assess);const cols=['po','supplier','part','severity','late','slip','short','job','need','eta','action'];download('supplier-action-plan.csv',[cols.join(','),...rows.map(r=>cols.map(k=>csvCell(k==='action'?(state.actions[r.po]?'Follow-up recorded':'Awaiting review'):r[k])).join(','))].join('\r\n'),'text/csv');};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('Use a CSV smaller than 1 MB.');const orders=parseCSV(await f.text());state={orders,actions:{},logs:[{time:new Date().toISOString(),text:`Imported ${orders.length} order lines from ${f.name}. Previous dataset replaced.`}]};save();render();toast(`Imported ${orders.length} orders. Previous dataset replaced.`);}catch(err){toast(err.message);}e.target.value='';};$('#search').oninput=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$('#showAll').onclick=()=>{filter='All';render();};$('#close').onclick=()=>$('#detail').close();$('#reset').onclick=()=>{if(!confirm('Replace the current dataset and activity with the sample demo?'))return;state={orders:structuredClone(demo),actions:{},logs:[]};save();render();toast('Sample demo restored.');};$('#auditBtn').onclick=()=>{$('#auditBody').innerHTML=state.logs.length?state.logs.map(l=>`<div class="log">${esc(l.text)}<small>${esc(new Date(l.time).toLocaleString())}</small></div>`).join(''):'<p>No activity yet. Import orders or record a follow-up to begin.</p>';$('#audit').showModal();};$('#closeAudit').onclick=()=>$('#audit').close();render();

// UI extensions share the existing browser-local workspace and decision engine.
const baseRender=render, baseDetail=openDetail;
state.notes??={};
const svgIcon=(path)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true">${path}</svg>`;
document.querySelector('header').innerHTML=`<span><span class="live-dot"></span> Fort Worth operations <span class="header-slash">/</span> <b>Supply desk</b></span><div class="header-tools"><span class="snapshot">Planning workspace</span><button id="theme" aria-label="Toggle dark theme">☾</button><span class="avatar">FW</span></div>`;
document.querySelector('.heading .eyebrow').textContent='YOUR SUPPLY CHAIN, IN FOCUS';
document.querySelector('.heading h1').innerHTML='Small signals.<br><span>Stronger operations.</span>';
document.querySelector('.heading p').textContent='A clearer view of what’s arriving, what’s at risk, and what comes next.';
document.querySelector('.metrics').insertAdjacentHTML('beforebegin','<section id="spotlight" class="spotlight"></section>');
document.querySelector('.board').insertAdjacentHTML('beforebegin','<section class="insight-grid"><div class="insight-panel"><div class="panel-title"><div><span class="eyebrow">NETWORK OVERVIEW</span><h2>Supplier health</h2></div><span class="subtle-tag">Current confirmations</span></div><div id="health"></div></div><div class="insight-panel timeline-panel"><div class="panel-title"><div><span class="eyebrow">ON THE HORIZON</span><h2>Delivery timeline</h2></div><span class="timeline-key"><i></i> ETA</span></div><div id="timeline"></div></div></section>');
document.querySelector('.toolbar').insertAdjacentHTML('afterend','<div class="advanced-filters"><label>Supplier <select id="supplierFilter"><option value="">All suppliers</option></select></label><label>Workflow <select id="actionFilter"><option value="">All actions</option><option value="open">Awaiting follow-up</option><option value="recorded">Action recorded</option></select></label><button id="clearFilters">Clear filters</button><span id="filteredCount"></span></div>');
document.querySelector('nav').insertAdjacentHTML('beforeend','<button id="supplierNav">◉ &nbsp; Supplier network</button><button id="timelineNav">▤ &nbsp; Delivery timeline</button>');
document.querySelector('.sidefoot').insertAdjacentHTML('beforebegin','<div class="sidebar-card"><span>BUILT FOR THE FLOOR</span><h3>Keep the line moving.</h3><p>Every exception is an opportunity to act sooner.</p><div class="mini-orbit"><i></i><i></i><i></i></div></div>');
document.querySelector('#supplierNav').onclick=()=>document.querySelector('.insight-grid').scrollIntoView({behavior:'smooth',block:'start'});
document.querySelector('#timelineNav').onclick=()=>document.querySelector('.timeline-panel').scrollIntoView({behavior:'smooth',block:'center'});
const setTheme=d=>{document.documentElement.dataset.theme=d?'dark':'light';$('#theme').textContent=d?'☀':'☾';$('#theme').setAttribute('aria-label',d?'Switch to light theme':'Switch to dark theme');};
try{setTheme(localStorage.getItem('supplysignal-theme')==='dark');}catch{}
$('#theme').onclick=()=>{const d=document.documentElement.dataset.theme!=='dark';setTheme(d);try{localStorage.setItem('supplysignal-theme',d?'dark':'light');}catch{}};
render=function(){
 baseRender();const all=state.orders.map(assess),critical=all.filter(x=>x.severity==='Critical').sort((a,b)=>b.slip-a.slip||b.short-a.short),top=critical.find(x=>!state.actions[x.po])??critical[0];
 const good=all.filter(x=>x.severity==='On track').length,pct=all.length?Math.round(good/all.length*100):0;
 $('#spotlight').innerHTML=`<div class="spotlight-copy"><span class="spotlight-tag"><i></i> ${top?'PRIORITY BRIEFING':'OPERATIONS BRIEFING'}</span><h2>${top?`${esc(top.supplier)} needs your attention.`:'Your desk is clear of critical exceptions.'}</h2><p>${top?`${esc(top.po)} · ${top.slip?`${top.slip} days beyond the production need date`: `${top.short} units below the order quantity`}. Review recovery options before the next planning meeting.`:'Review the delivery timeline and keep supplier confirmations current.'}</p><button id="priorityReview">${top?'Review priority order':'View purchase orders'} <span>↗</span></button></div><div class="orbital" aria-label="'+pct+' percent of order lines on track"><div class="orbit-line"></div><div class="orbit-line second"></div><div class="orbit-core"><strong>${pct}<em>%</em></strong><span>ORDER LINES<br>ON TRACK</span></div><span class="satellite s1"></span><span class="satellite s2"></span><span class="orbit-caption">VISIBILITY → CONFIDENCE</span></div>`;
 $('.orbital').setAttribute('aria-label',`${pct} percent of order lines on track`);
 $('#priorityReview').onclick=()=>top?openDetail(top.po):($('#showAll').click());
 const groups=[...new Set(all.map(x=>x.supplier))].map(name=>{const orders=all.filter(x=>x.supplier===name);return {name,orders,critical:orders.filter(x=>x.severity==='Critical').length,watch:orders.filter(x=>x.severity==='Watch').length};}).sort((a,b)=>b.critical-a.critical||b.watch-a.watch);
 $('#health').innerHTML=groups.map(g=>`<button class="supplier-row" data-supplier="${esc(g.name)}"><span class="supplier-monogram">${esc(g.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span class="supplier-name"><b>${esc(g.name)}</b><small>${g.orders.length} order line${g.orders.length===1?'':'s'}</small></span><span class="health-track"><i style="width:${100*(g.orders.length-g.critical-g.watch)/g.orders.length}%;background:#92ad66"></i><i style="width:${100*g.watch/g.orders.length}%;background:#dab977"></i><i style="width:${100*g.critical/g.orders.length}%;background:#d28f77"></i></span><span class="health-caption">${g.critical?g.critical+' critical':g.watch?g.watch+' to watch':'On track'}</span><span>↗</span></button>`).join('');
 const supplierValue=$('#supplierFilter').value;$('#supplierFilter').innerHTML='<option value="">All suppliers</option>'+groups.map(g=>`<option>${esc(g.name)}</option>`).join('');$('#supplierFilter').value=supplierValue;
 document.querySelectorAll('[data-supplier]').forEach(b=>b.onclick=()=>{$('#supplierFilter').value=b.dataset.supplier;filter='All';render();document.querySelector('.board').scrollIntoView({behavior:'smooth'});});
 $('#timeline').innerHTML=all.slice().sort((a,b)=>a.eta.localeCompare(b.eta)).slice(0,5).map(r=>`<button class="timeline-row" data-timeline="${esc(r.po)}"><span class="timeline-date">${date(r.eta)}</span><span class="timeline-node ${r.severity}"></span><span><b>${esc(r.po)}</b><small>${esc(r.part)}</small></span><span class="timeline-status ${r.severity==='Critical'?'signal':''}">${r.slip?'Need +'+r.slip+'d':r.late?'Promise +'+r.late+'d':'On time'}</span></button>`).join('');document.querySelectorAll('[data-timeline]').forEach(b=>b.onclick=()=>openDetail(b.dataset.timeline));
 let visible=0;document.querySelectorAll('#rows tr').forEach(tr=>{const po=tr.querySelector('[data-po]')?.dataset.po;if(!po)return;const r=all.find(x=>x.po===po),status=$('#actionFilter').value;const show=(!supplierValue||r.supplier===supplierValue)&&(!status||(status==='recorded'?!!state.actions[po]:!state.actions[po]));tr.hidden=!show;if(show)visible++;});$('#filteredCount').textContent=`${visible} visible order${visible===1?'':'s'}`;
 const old=$('#filterEmpty');if(old)old.remove();if(!visible&&$('#rows [data-po]'))$('#rows').insertAdjacentHTML('beforeend','<tr id="filterEmpty"><td colspan="5">No orders match these filters. Clear filters to see the full desk.</td></tr>');
 const b=$('.banner span');b.textContent=state.logs.some(l=>l.text.startsWith('Imported '))?'◈ Imported workspace · Your CSV data, stored in this browser. No live ERP connection.':'◈ Sample workspace · Fictional orders for a HackFW demo. No live ERP connection.';
};
$('#supplierFilter').onchange=render;$('#actionFilter').onchange=render;$('#clearFilters').onclick=()=>{$('#supplierFilter').value='';$('#actionFilter').value='';$('#search').value='';filter='Exceptions';render();};
openDetail=function(po){baseDetail(po);const r=state.orders.find(x=>x.po===po);$('#detailBody').insertAdjacentHTML('beforeend',`<section class="planner"><h3>Update delivery confirmation</h3><p>Save a supplier’s revised confirmation to recalculate the exception.</p><form id="confirmationForm"><div class="formgrid"><label>Confirmed arrival<input id="newEta" type="date" value="${esc(r.eta)}" required></label><label>Confirmed quantity<input id="newQty" type="number" min="0" step="1" value="${r.confirmed}" required></label></div><button class="primary" type="submit">Save confirmation & recalculate</button></form><h3>Planner notes</h3><textarea id="plannerNote" placeholder="Owner, recovery options, next check-in…" aria-label="Planner notes"></textarea><button id="saveNote">Save note</button></section>`);$('#plannerNote').value=state.notes?.[po]??'';$('#saveNote').onclick=()=>{state.notes??={};state.notes[po]=$('#plannerNote').value;state.logs.unshift({time:new Date().toISOString(),text:`Planner note saved for ${po}.`});save();toast('Planner note saved.');};$('#confirmationForm').onsubmit=e=>{e.preventDefault();const eta=$('#newEta').value,qty=Number($('#newQty').value);if(!Number.isSafeInteger(qty)||qty<0||!eta||!Number.isFinite(Date.parse(eta))){toast('Enter a valid date and a nonnegative whole quantity.');return;}const before=`${r.eta}, ${r.confirmed} units`;r.eta=eta;r.confirmed=qty;delete state.actions[po];state.logs.unshift({time:new Date().toISOString(),text:`${po} confirmation changed from ${before} to ${eta}, ${qty} units. Follow-up review reopened.`});save();render();$('#detail').close();toast('Confirmation updated. Risk recalculated and follow-up reopened.');};};
render();

$('#search').oninput=()=>render();
